// Define the missing calibration constants (Typical STM32 values)
const V_AT_25C = 0.76;  // Volts at 25°C
const AVG_SLOPE = 2.5;  // mV/°C

// Generate mock data
let ADC1IN1 = Math.floor(Math.random() * 4096);
let BLUELED = Math.round(Math.random());
let voltage1 = (ADC1IN1 * 3.3) / 4095;
let TEMPSENSOR = Math.floor(Math.random() * 1000) + 500; 

let v_ref = (1.21 * 4095) / (Math.floor(Math.random() * 1000) + 1000); 
let v_sense = (TEMPSENSOR * v_ref) / 4095;

// FIXED: Removed the 'f' suffixes from 1000.0 and 25.0
let temp = ((v_sense - V_AT_25C) * 1000.0 / AVG_SLOPE) + 25.0; 
let VREFINT = Math.floor(Math.random() * 1000) + 1000; 

// Format the decimals safely before sending to SQL
voltage1 = Number(voltage1.toFixed(2));
v_ref = Number(v_ref.toFixed(2));
v_sense = Number(v_sense.toFixed(2));
temp = Number(temp.toFixed(2));

// Prepare the SQL query statement
msg.topic = `INSERT INTO sensor_data (ADC1IN1, voltage1, BLUELED, TEMPSENSOR, v_ref, v_sense, temp, VREFINT)
             VALUES (${ADC1IN1}, ${voltage1}, ${BLUELED}, ${TEMPSENSOR}, ${v_ref}, ${v_sense}, ${temp}, ${VREFINT});`;

return msg;

